<template><ion-page><ion-header class="ion-no-border"><ion-toolbar><ion-title>Goat inventory</ion-title></ion-toolbar><ion-toolbar><ion-searchbar v-model="search" :debounce="350" placeholder="Search ID, name, or tag" @ionInput="load" /></ion-toolbar></ion-header><ion-content><main class="page-wrap compact-top">
  <div class="list-summary"><p><strong>{{ total }}</strong> farm goats</p><ion-select v-model="filter" interface="popover" aria-label="Status"><ion-select-option value="all">All statuses</ion-select-option><ion-select-option value="active">Active</ion-select-option><ion-select-option value="missing">Missing</ion-select-option><ion-select-option value="sold">Sold</ion-select-option></ion-select></div>
  <StatePanel v-if="loading" loading title="Loading goats" message="Retrieving the farm inventory." /><StatePanel v-else-if="error" tone="danger" title="Unable to retrieve goat inventory" :message="error" :retry="load" /><StatePanel v-else-if="!visible.length" title="No goats found" message="Try a different search or filter." />
  <section v-else class="goat-list"><article v-for="goat in visible" :key="goat.id" class="goat-card" @click="$router.push(`/goats/${goat.goat_id}`)"><AuthImage :src="goat.cover_image_url" :alt="goat.name || goat.goat_id" /><div class="goat-card-body"><div><span class="goat-id">{{ goat.goat_id }}</span><span class="status-pill" :class="goat.status">{{ titleCase(goat.status) }}</span></div><h2>{{ goat.name || 'Unnamed goat' }}</h2><p>{{ goat.breed_display }} · {{ goat.gender_display }} · {{ goat.age }}</p><div class="goat-facts"><span><b>{{ goat.latest_weight?.weight_kg || goat.weight_kg || '—' }}</b> kg</span><span><b>{{ titleCase(goat.health_status) }}</b> health</span></div></div><ion-icon class="chevron" :icon="chevronForwardOutline" /></article></section>
</main></ion-content></ion-page></template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { IonContent, IonHeader, IonIcon, IonPage, IonSearchbar, IonSelect, IonSelectOption, IonTitle, IonToolbar } from '@ionic/vue'; import { chevronForwardOutline } from 'ionicons/icons'; import AuthImage from '@/components/AuthImage.vue'; import StatePanel from '@/components/StatePanel.vue'; import { goatService } from '@/services/goat.service'; import type { Goat } from '@/types/api'; import { titleCase } from '@/utils/format';
const goats = ref<Goat[]>([]); const total = ref(0); const search = ref(''); const filter = ref('all'); const loading = ref(true); const error = ref(''); const visible = computed(() => filter.value === 'all' ? goats.value : goats.value.filter((goat) => goat.status === filter.value));
async function load() { loading.value = true; error.value = ''; try { const result = await goatService.list(search.value); goats.value = result.results; total.value = result.count; } catch (reason) { error.value = reason instanceof Error ? reason.message : 'Unable to load goats.'; } finally { loading.value = false; } } onMounted(load);
</script>
